// S15 acceptance (TICK-443): fresh access tokens for requests that outlive one.
// The S15 folders poll for up to 330 s, longer than the realm's access token
// lifetime, so every request (folder pre-request script) and every poll round
// calls fresh() first.
// Generated by docs/acceptance/guide/build/collection.py; edit it there.
const USERS = {
  operator_token: ['operator_username', 'operator_password', 'nava-operator-cli'],
  auditor_token: ['auditor_a_username', 'auditor_a_password', 'nava-web'],
  alice_token: ['alice_username', 'alice_password', 'nava-web'],
  bob_token: ['bob_username', 'bob_password', 'nava-web'],
};

module.exports = (N, bru) => ({
  // fresh(...vars): signs in again for each token variable that is set and
  // expires within 60 s.
  async fresh(...vars) {
    for (const v of vars.length ? vars : Object.keys(USERS)) {
      const t = bru.getVar(v);
      if (!t || !USERS[v]) continue;
      if (N.jwt(t).exp * 1000 - Date.now() > 60000) continue;
      const [u, p, client] = USERS[v];
      const r = await N.token(N.v(u), N.v(p), { client });
      if (r.status !== 200) throw new Error(`sign-in again for ${v}: HTTP ${r.status}`);
      bru.setVar(v, r.data.access_token);
    }
  },
});
